/**
 * Unit tests for FieldFormatter.printTo
 */
public class FieldFormatter_printTo_TriageGen0Test {

    /**
     * Since FieldFormatter is an inner class of PeriodFormatterBuilder and has no public constructor,
     * we must use the PeriodFormatterBuilder to instantiate it.
     * However, because the fields (iFieldType, iPrefix, iSuffix, iMinPrintedDigits) are private,
     * we use the Builder API to configure the state of the FieldFormatter.
     */

